#!/usr/bin/env bash
# Prints the Homebrew formula for a firebrick release on stdout.
#
# Usage: homebrew-formula.sh <tag> <directory with the .sha256 files>
#
# The directory holds the firebrick-<tag>-<target>.tar.gz.sha256 files the release workflow's package job
# writes, for the macOS (Apple Silicon) and Linux targets.
set -euo pipefail

if [ $# -ne 2 ]; then
  echo "usage: $0 <tag> <directory with the .sha256 files>" >&2
  exit 2
fi

tag=$1
dir=$2

# Pre-releases such as v0.2.0-rc.1 don't go to the tap.
if ! [[ $tag =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  echo "error: tag $tag doesn't look like v<major>.<minor>.<patch>" >&2
  exit 1
fi
base="https://github.com/wmeints/firebrick/releases/download/$tag"

# Prints the sha256 of a target's archive, read from the first field of its .sha256 file.
checksum() {
  local file="$dir/firebrick-$tag-$1.tar.gz.sha256"
  if [ ! -f "$file" ]; then
    echo "error: $file is missing" >&2
    return 1
  fi
  local sum
  read -r sum _ < "$file"
  if ! [[ $sum =~ ^[0-9a-f]{64}$ ]]; then
    echo "error: $file doesn't hold a sha256 checksum" >&2
    return 1
  fi
  echo "$sum"
}

macos_arm=$(checksum aarch64-apple-darwin)
linux_intel=$(checksum x86_64-unknown-linux-gnu)
linux_arm=$(checksum aarch64-unknown-linux-gnu)

cat <<EOF
# Generated by .github/scripts/homebrew-formula.sh in wmeints/firebrick; don't edit it by hand.
class Firebrick < Formula
  desc "Run coding agents in microVM sandboxes"
  homepage "https://firebrick-sandbox.dev"
  license "MIT"

  on_macos do
    # microsandbox only supports Apple Silicon on macOS.
    depends_on arch: :arm64

    on_arm do
      url "$base/firebrick-$tag-aarch64-apple-darwin.tar.gz"
      sha256 "$macos_arm"
    end
  end

  on_linux do
    on_intel do
      url "$base/firebrick-$tag-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "$linux_intel"
    end

    on_arm do
      url "$base/firebrick-$tag-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "$linux_arm"
    end
  end

  def install
    # fbk starts the fbkd next to it, so both go in the same directory.
    bin.install "fbk", "fbkd"
  end

  test do
    assert_equal "fbk #{version}", shell_output("#{bin}/fbk --version").strip
  end
end
EOF
